import datetime
import os
import sys


LOG_PATH = os.path.expanduser("~/Library/Application Support/plover/plover_debug.log")
KOREAN_SYSTEM_NAME = "Korean Modern C"
DESIRED_MACHINE_TYPE = "Keyboard"


def _debug(message):
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as handle:
            handle.write(message + "\n")
    except Exception:
        pass


def _log_startup():
    _debug(f"\n=== {datetime.datetime.now()} ===")
    _debug(f"sys.executable: {sys.executable}")
    for path in sys.path:
        _debug(f"  PATH: {path}")
    try:
        import plover_korean.system.cas.definition as definition

        _debug(f"definition.__file__: {definition.__file__}")
        _debug(f"DEFAULT_DICTIONARIES: {definition.DEFAULT_DICTIONARIES}")
    except Exception as exc:
        _debug(f"ERROR: {exc}")


def _korean_dictionary_paths():
    try:
        import plover_korean.system.cas.definition as definition

        return list(definition.DEFAULT_DICTIONARIES)
    except Exception as exc:
        _debug(f"PATCH_DICT_PATHS_FAILED {exc!r}")
        return [
            os.path.expanduser(
                "~/Library/Application Support/plover/plugins/mac/lib/python/"
                "site-packages/plover_korean/system/cas/dictionaries/"
                "ko_cas_numbers.py"
            ),
            os.path.expanduser(
                "~/Library/Application Support/plover/plugins/mac/lib/python/"
                "site-packages/plover_korean/system/cas/dictionaries/"
                "ko_cas_base.py"
            ),
        ]


def _patch_config_defaults():
    try:
        import plover.config as plover_config
        from plover.config import DictionaryConfig
    except Exception as exc:
        _debug(f"PATCH_CONFIG_SKIP import failed: {exc}")
        return

    dictionary_paths = _korean_dictionary_paths()
    original_load = plover_config.Config.load
    original_update = plover_config.Config.update

    def _desired_dictionary_configs():
        return [DictionaryConfig(path, True) for path in dictionary_paths]

    def _dictionary_tuples(configs):
        return [
            (getattr(config, "path", None), getattr(config, "enabled", None))
            for config in configs
        ]

    def _normalize_config(config, reason, save=False):
        changed = False
        try:
            current_system = config["system_name"]
        except Exception as exc:
            _debug(f"PATCH_CONFIG_READ_FAILED reason={reason} key=system_name error={exc!r}")
            current_system = None
        try:
            current_dictionaries = config["dictionaries"]
        except Exception as exc:
            _debug(f"PATCH_CONFIG_READ_FAILED reason={reason} key=dictionaries error={exc!r}")
            current_dictionaries = []
        try:
            current_machine_type = config["machine_type"]
        except Exception as exc:
            _debug(
                f"PATCH_CONFIG_READ_FAILED reason={reason} key=machine_type error={exc!r}"
            )
            current_machine_type = None
        desired_dictionaries = _desired_dictionary_configs()
        if current_system != KOREAN_SYSTEM_NAME:
            changed = True
        if _dictionary_tuples(current_dictionaries) != _dictionary_tuples(desired_dictionaries):
            changed = True
        if current_machine_type != DESIRED_MACHINE_TYPE:
            changed = True
        if not changed:
            _debug(
                f"PATCH_CONFIG_OK reason={reason} "
                f"system={current_system!r} "
                f"dictionaries={_dictionary_tuples(current_dictionaries)!r} "
                f"machine_type={current_machine_type!r}"
            )
            return False
        original_update(
            config,
            system_name=KOREAN_SYSTEM_NAME,
            dictionaries=desired_dictionaries,
            machine_type=DESIRED_MACHINE_TYPE,
        )
        _debug(
            f"PATCH_CONFIG_NORMALIZED reason={reason} "
            f"from_system={current_system!r} "
            f"to_system={KOREAN_SYSTEM_NAME!r} "
            f"from_machine_type={current_machine_type!r} "
            f"to_machine_type={DESIRED_MACHINE_TYPE!r}"
        )
        if save:
            try:
                config.save()
                _debug(f"PATCH_CONFIG_SAVED reason={reason}")
            except Exception as exc:
                _debug(f"PATCH_CONFIG_SAVE_FAILED reason={reason} error={exc!r}")
        return True

    def patched_load(self):
        result = original_load(self)
        _normalize_config(self, "load", save=True)
        return result

    def patched_update(self, **kwargs):
        requested_machine_type = kwargs.get("machine_type")
        if (
            kwargs.get("system_name") != KOREAN_SYSTEM_NAME
            or "dictionaries" in kwargs
            or requested_machine_type != DESIRED_MACHINE_TYPE
        ):
            kwargs["system_name"] = KOREAN_SYSTEM_NAME
            kwargs["dictionaries"] = _desired_dictionary_configs()
            kwargs["machine_type"] = DESIRED_MACHINE_TYPE
            _debug(
                "PATCH_UPDATE_OVERRIDE "
                f"keys={sorted(kwargs)!r} "
                f"requested_machine_type={requested_machine_type!r}"
            )
        return original_update(self, **kwargs)

    system_option = plover_config.Config._OPTIONS["system_name"]
    dictionaries_option = plover_config.Config._OPTIONS["dictionaries"]
    machine_type_option = plover_config.Config._OPTIONS["machine_type"]
    plover_config.DEFAULT_SYSTEM_NAME = KOREAN_SYSTEM_NAME
    plover_config.Config._OPTIONS["system_name"] = system_option._replace(
        default=lambda _config, _key: KOREAN_SYSTEM_NAME
    )
    plover_config.Config._OPTIONS["dictionaries"] = dictionaries_option._replace(
        default=lambda _config, _key: _desired_dictionary_configs()
    )
    plover_config.Config._OPTIONS["machine_type"] = machine_type_option._replace(
        default=lambda _config, _key: DESIRED_MACHINE_TYPE
    )
    plover_config.Config.load = patched_load
    plover_config.Config.update = patched_update
    _debug(
        "PATCH_CONFIG_APPLIED "
        f"default_system={KOREAN_SYSTEM_NAME!r} "
        f"default_dictionaries={dictionary_paths!r} "
        f"default_machine_type={DESIRED_MACHINE_TYPE!r}"
    )


def _patch_dictionaries_widget():
    _debug("PATCH_WIDGET_SYNC_DISABLED")


_log_startup()
_patch_config_defaults()
_patch_dictionaries_widget()
